        console.error("Nessun dato disponibile per il download del PDF");
        alert("Errore: Nessun dato disponibile per il download del PDF");
        return;
      }

      // Aggiorna il modello del widget con tutti i dati necessari
      appsmith.updateModel({ 
        data: JSON.stringify(data), 
        edited: JSON.stringify(edited),
        allData: finalData,
        isReady: true,
        lastAction: 'pdf_download',
        timestamp: new Date().toISOString(),
        userInfo: {
